int arr[50];
int len;

void bubble_sort(int* array, int len) {
    for (int i = 0; i < len - 1; i++) {
        for (int j = 0; j < len – 1 – i; j++) {
            if (array[j] > array[j + 1]) {
                int temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }
}

int main() {
    scanf("%d", &len);
    for (int i = 0; i < len; i++) arr[i] = rand() % 100;

    for (int i = 0; i < len; i++) printf("%d ", arr[i]);
    printf("\n");

    bubble_sort(arr, len);

    for (int i = 0; i < len; i++) printf("%d ", arr[i]);
    printf("\n");

    return 0;
}

